CREATE TABLE "TB_LEGACY_BRF" (
  "LEGACY_BRF_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "GENERATED_DTTM" TIMESTAMPTZ,
  "MARKET_BASE_DT" DATE,
  "RECOVERY_DT" DATE NOT NULL,
  "BRF_TP" VARCHAR(20),
  "SOURCE_TP" VARCHAR(30) NOT NULL DEFAULT 'CHATGPT_CONVERSATION',
  "CONVERSATION_TITLE" VARCHAR(300),
  "CONVERSATION_ID" VARCHAR(100),
  "MESSAGE_ID" VARCHAR(100),
  "SELECTED_MESSAGE_ID" VARCHAR(100),
  "ORIGINAL_TEXT" TEXT,
  "ORIGINAL_HASH" CHAR(64),
  "RECOVERY_STS" VARCHAR(20) NOT NULL,
  "ISSUE_TXT" VARCHAR(1000),
  "CANDIDATE_CNT" INTEGER NOT NULL DEFAULT 0,
  "SOURCE_META_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "IMPORT_BATCH_ID" UUID NOT NULL,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_LEGACY_BRF_01" UNIQUE ("RECOVERY_DT", "SOURCE_TP"),
  CONSTRAINT "CK_TB_LEGACY_BRF_01" CHECK ("BRF_TP" IS NULL OR "BRF_TP" IN ('DAILY','WEEKLY','MONTHLY','AD_HOC')),
  CONSTRAINT "CK_TB_LEGACY_BRF_02" CHECK ("RECOVERY_STS" IN ('RECOVERED','INCOMPLETE','MISSING')),
  CONSTRAINT "CK_TB_LEGACY_BRF_03" CHECK ("CANDIDATE_CNT" >= 0),
  CONSTRAINT "CK_TB_LEGACY_BRF_04" CHECK (("RECOVERY_STS"='RECOVERED') = ("ORIGINAL_TEXT" IS NOT NULL))
);
CREATE INDEX "IDX_TB_LEGACY_BRF_01" ON "TB_LEGACY_BRF" ("MARKET_BASE_DT" DESC);
CREATE INDEX "IDX_TB_LEGACY_BRF_02" ON "TB_LEGACY_BRF" ("RECOVERY_STS", "RECOVERY_DT" DESC);
CREATE INDEX "IDX_TB_LEGACY_BRF_03" ON "TB_LEGACY_BRF" USING GIN ("SOURCE_META_JSON");
CREATE UNIQUE INDEX "UK_TB_LEGACY_BRF_02" ON "TB_LEGACY_BRF" ("MESSAGE_ID") WHERE "MESSAGE_ID" IS NOT NULL;

CREATE TABLE "TB_LEGACY_BRF_EXTRACT" (
  "LEGACY_EXTRACT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LEGACY_BRF_ID" BIGINT NOT NULL REFERENCES "TB_LEGACY_BRF"("LEGACY_BRF_ID") ON DELETE CASCADE,
  "EXTRACT_VER" INTEGER NOT NULL,
  "MKT_RISK_SCR" INTEGER,
  "MKT_PHASE_RAW" VARCHAR(300),
  "MKT_PHASE_CD" VARCHAR(50),
  "REG_BUY_SIG_RAW" VARCHAR(300),
  "REG_BUY_SIG_CD" VARCHAR(50),
  "ADD_BUY_SIG_RAW" VARCHAR(300),
  "ADD_BUY_SIG_CD" VARCHAR(50),
  "CASH_INPUT_RT" NUMERIC(7,4),
  "EXTRACTED_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "EXTRACT_CONF_RT" NUMERIC(7,4) NOT NULL,
  "REVIEW_STS" VARCHAR(20) NOT NULL,
  "REVIEW_NOTE" VARCHAR(2000),
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_LEGACY_BRF_EXTRACT_01" UNIQUE ("LEGACY_BRF_ID", "EXTRACT_VER"),
  CONSTRAINT "CK_TB_LEGACY_BRF_EXTRACT_01" CHECK ("EXTRACT_VER">0),
  CONSTRAINT "CK_TB_LEGACY_BRF_EXTRACT_02" CHECK ("MKT_RISK_SCR" IS NULL OR "MKT_RISK_SCR" BETWEEN 0 AND 100),
  CONSTRAINT "CK_TB_LEGACY_BRF_EXTRACT_03" CHECK ("CASH_INPUT_RT" IS NULL OR "CASH_INPUT_RT" BETWEEN 0 AND 100),
  CONSTRAINT "CK_TB_LEGACY_BRF_EXTRACT_04" CHECK ("EXTRACT_CONF_RT" BETWEEN 0 AND 100),
  CONSTRAINT "CK_TB_LEGACY_BRF_EXTRACT_05" CHECK ("REVIEW_STS" IN ('AUTO','REVIEW_REQUIRED','REVIEWED','REJECTED'))
);
CREATE INDEX "IDX_TB_LEGACY_BRF_EXTRACT_01" ON "TB_LEGACY_BRF_EXTRACT" ("MKT_RISK_SCR", "MKT_PHASE_CD");

CREATE TABLE "TB_HIST_RECALC_RUN" (
  "HIST_RECALC_RUN_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LEGACY_BRF_ID" BIGINT REFERENCES "TB_LEGACY_BRF"("LEGACY_BRF_ID"),
  "BASE_DT" DATE NOT NULL,
  "RUN_TP" VARCHAR(30) NOT NULL DEFAULT 'HISTORICAL_RECALC',
  "RULE_VER" VARCHAR(100) NOT NULL,
  "CODE_VER" VARCHAR(100),
  "RECONSTRUCTION_MODE" VARCHAR(30) NOT NULL,
  "PORTFOLIO_MODE" VARCHAR(30) NOT NULL,
  "DATA_STS" VARCHAR(30) NOT NULL,
  "RUN_STS" VARCHAR(20) NOT NULL,
  "INPUT_BASE_DT_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "AVAILABILITY_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "MISSING_INPUT_JSON" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "RESULT_JSON" JSONB,
  "FAIL_RSN" VARCHAR(2000),
  "START_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "END_DTTM" TIMESTAMPTZ,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_TB_HIST_RECALC_RUN_01" CHECK ("RUN_TP"='HISTORICAL_RECALC'),
  CONSTRAINT "CK_TB_HIST_RECALC_RUN_02" CHECK ("RECONSTRUCTION_MODE" IN ('POINT_IN_TIME','AS_OF_RECONSTRUCTED','HYBRID')),
  CONSTRAINT "CK_TB_HIST_RECALC_RUN_03" CHECK ("PORTFOLIO_MODE" IN ('MARKET_ONLY','POINT_IN_TIME','CURRENT_PORTFOLIO_SIMULATION','NOT_REPRODUCIBLE')),
  CONSTRAINT "CK_TB_HIST_RECALC_RUN_04" CHECK ("DATA_STS" IN ('COMPLETE','PARTIAL','NOT_COMPARABLE','NOT_REPRODUCIBLE','FAILED','SKIPPED')),
  CONSTRAINT "CK_TB_HIST_RECALC_RUN_05" CHECK ("RUN_STS" IN ('RUNNING','SUCCESS','FAILED','SKIPPED'))
);
CREATE INDEX "IDX_TB_HIST_RECALC_RUN_01" ON "TB_HIST_RECALC_RUN" ("BASE_DT" DESC, "START_DTTM" DESC);
CREATE INDEX "IDX_TB_HIST_RECALC_RUN_02" ON "TB_HIST_RECALC_RUN" ("LEGACY_BRF_ID", "START_DTTM" DESC);

CREATE TABLE "TB_BRF_EVAL" (
  "BRF_EVAL_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "LEGACY_BRF_ID" BIGINT REFERENCES "TB_LEGACY_BRF"("LEGACY_BRF_ID") ON DELETE CASCADE,
  "HIST_RECALC_RUN_ID" BIGINT REFERENCES "TB_HIST_RECALC_RUN"("HIST_RECALC_RUN_ID") ON DELETE CASCADE,
  "BASE_DT" DATE NOT NULL,
  "TARGET_CD" VARCHAR(50) NOT NULL,
  "HORIZON_BD" INTEGER NOT NULL,
  "RETURN_RT" NUMERIC(12,6),
  "MAX_DRAWDOWN_RT" NUMERIC(12,6),
  "MAX_RUNUP_RT" NUMERIC(12,6),
  "EVAL_STS" VARCHAR(20) NOT NULL,
  "EVAL_RULE_VER" VARCHAR(100) NOT NULL,
  "DETAIL_JSON" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "CRT_DTTM" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "UK_TB_BRF_EVAL_01" UNIQUE NULLS NOT DISTINCT ("LEGACY_BRF_ID","HIST_RECALC_RUN_ID","TARGET_CD","HORIZON_BD","EVAL_RULE_VER"),
  CONSTRAINT "CK_TB_BRF_EVAL_01" CHECK ("HORIZON_BD">0),
  CONSTRAINT "CK_TB_BRF_EVAL_02" CHECK ("EVAL_STS" IN ('READY','COMPLETE','PARTIAL','NOT_AVAILABLE','FAILED')),
  CONSTRAINT "CK_TB_BRF_EVAL_03" CHECK ("LEGACY_BRF_ID" IS NOT NULL OR "HIST_RECALC_RUN_ID" IS NOT NULL)
);
CREATE INDEX "IDX_TB_BRF_EVAL_01" ON "TB_BRF_EVAL" ("BASE_DT" DESC, "TARGET_CD", "HORIZON_BD");

COMMENT ON TABLE "TB_LEGACY_BRF" IS '원천 Snapshot 없이 복원한 과거 ChatGPT 투자판단 원본';
COMMENT ON TABLE "TB_LEGACY_BRF_EXTRACT" IS 'LEGACY 브리핑 원문에서 명시적으로 추출한 버전별 구조화 판단';
COMMENT ON TABLE "TB_HIST_RECALC_RUN" IS '운영 최신 브리핑과 분리된 과거 시장 알고리즘 재계산 실행이력';
COMMENT ON TABLE "TB_BRF_EVAL" IS 'LEGACY 판단 및 역사 재계산 결과의 사후 성과평가';
COMMENT ON COLUMN "TB_LEGACY_BRF"."MARKET_BASE_DT" IS '본문이 실제로 판단한 시장 기준일. 메시지 생성일과 다를 수 있음';
COMMENT ON COLUMN "TB_HIST_RECALC_RUN"."RECONSTRUCTION_MODE" IS '당시 저장 Snapshot인지 현재 백필 재구성인지 나타내는 데이터 계보';
